"""Export actual resource measurements without altering raw evidence."""
import argparse,gzip,hashlib,json,pathlib,re,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1];PROFILES=['middleware-fixed','proxy-fixed','middleware-adaptive','proxy-adaptive'];STRATEGIES=['disabled','observe','enforce'];PHASES=['healthy','memory','goroutines','writes','hot-keys','recovery']
def main():
 p=argparse.ArgumentParser();p.add_argument('--report',type=pathlib.Path,required=True);p.add_argument('--overhead',type=pathlib.Path,required=True);a=p.parse_args();raw=a.report.read_bytes();d=json.loads(raw);assert d.get('passed') and len(d['runs'])==36 and all(r['passed'] for r in d['runs']);rows=[]
 for profile in PROFILES:
  for strategy in STRATEGIES:
   runs=[r for r in d['runs'] if r['profile']==profile and r['strategy']==strategy];assert len(runs)==3
   for phase in PHASES:
    phases=[next(p for p in r['phases'] if p['name']==phase) for r in runs];probes=[p['tenant_traffic']['probe'] for p in phases];pressure=[p['tenant_traffic']['pressure'] for p in phases];sent=sum(v['sent'] for v in probes);pressureSent=sum(v['sent'] for v in pressure);waits=sum(v['wait_count'] for p in phases for v in p['pools'].values());waitsec=sum(v['wait_seconds'] for p in phases for v in p['pools'].values());points=[v for r in runs for v in r['trace'] if v['phase']==phase];states=[v for p in phases for v in p['resource_after'].values()]
    rows.append({'profile':profile,'strategy':strategy,'phase':phase,'probe_success_rps':statistics.median(v['successful']/p['offered_seconds'] for p,v in zip(phases,probes)),'probe_timely_rps':statistics.median(v['successful_within_100ms_per_offered_second'] for v in probes),'probe_p95_ms':statistics.median(v['successful_p95_ms'] for v in probes if v['successful_p95_ms'] is not None) if any(v['successful_p95_ms'] is not None for v in probes) else None,'probe_rejected_percent':sum(v['rejected_503'] for v in probes)/sent*100,'probe_errors_percent':sum(v['backend_5xx'] for v in probes)/sent*100,'pressure_success_rps':statistics.median(v['successful']/p['offered_seconds'] for p,v in zip(phases,pressure)),'pressure_rejected_percent':sum(v['rejected_503'] for v in pressure)/pressureSent*100,'pressure_errors_percent':sum(v['backend_5xx'] for v in pressure)/pressureSent*100,'mean_pool_wait_ms':waitsec/waits*1000 if waits else 0,'mean_allocation_mib_per_service':statistics.mean(v['resource']['allocation_live_bytes']/(1<<20) for v in points) if points else None,'mean_workers_per_service':statistics.mean(v['resource']['workers_active'] for v in points) if points else None,'peak_allocation_mib_per_service':max(v['allocation_peak_bytes'] for v in states)/(1<<20),'peak_workers_per_service':max(v['workers_peak'] for v in states),'peak_write_kib_per_service':max(v['write_bytes_peak'] for v in states)/1024,'peak_key_concurrency':max(v['key_peak_concurrent'] for v in states)})
 summary={'source_sha256':hashlib.sha256(raw).hexdigest(),'sent':sum(p['sent'] for r in d['runs'] for p in r['phases']),'runs':len(d['runs']),'checks':sum(len(r['checks']) for r in d['runs']),'missed':sum(p['dropped_schedules'] for r in d['runs'] for p in r['phases']),'transport_errors':sum(v['transport_errors'] for r in d['runs'] for p in r['phases'] for v in p['traffic'].values()),'rows':rows}
 overhead=a.overhead.read_text();bench={}
 for name,ns,byte,alloc in re.findall(r'^(Benchmark\S+?)-\d+\s+\d+\s+([\d.]+) ns/op\s+(\d+) B/op\s+(\d+) allocs/op',overhead,re.M):bench.setdefault(name,[]).append({'ns':float(ns),'bytes':int(byte),'allocs':int(alloc)})
 assert bench and all(len(v)==3 for v in bench.values());summary['overhead']=[{'name':k,'ns_median':statistics.median(v['ns'] for v in vals),'bytes':vals[0]['bytes'],'allocs':vals[0]['allocs']} for k,vals in bench.items()]
 (ROOT/'src/data/resource-platform.json').write_bytes((ROOT/'public/data/resource-platform-validation.json').read_bytes())
 out=ROOT/'public/data';(out/'resource-results.json').write_bytes(raw);(out/'resource-results.json.gz').write_bytes(gzip.compress(raw,mtime=0));(out/'resource-overhead.txt').write_text(overhead);(ROOT/'src/data/resources-benchmark.json').write_text(json.dumps(summary,indent=2)+'\n')
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'text.color':'#dae8df','axes.labelcolor':'#bccfc2','xtick.color':'#a9bfb0','ytick.color':'#cbdcd1','axes.edgecolor':'#45604f','figure.facecolor':'#101b16','axes.facecolor':'#101b16','savefig.facecolor':'#101b16'})
 colors={'disabled':'#829d8e','observe':'#bdab79','enforce':'#76d9bc'}
 fig,axes=plt.subplots(1,2,figsize=(16,8))
 for ax,phase,title in [(axes[0],'writes','Unrelated SQL reads during large writes'),(axes[1],'hot-keys','Cold-key writes during hot-key contention')]:
  selected=[r for r in rows if r['phase']==phase];labels=[r['profile'].replace('middleware-','Middleware / ').replace('proxy-','Proxy / ')+' · '+r['strategy'] for r in selected]
  ax.barh(range(len(selected)),[r['probe_timely_rps'] for r in selected],color=[colors[r['strategy']] for r in selected],height=.65);ax.set_yticks(range(len(selected)),labels);ax.invert_yaxis();ax.set_title(title,pad=18);ax.set_xlabel('Probe requests completed within 100 ms / sec');ax.axvline(48,color='#bbd6c6',linestyle='--',linewidth=1);ax.set_xlim(0,50);ax.grid(axis='x',alpha=.12);ax.set_axisbelow(True);ax.spines[['top','right']].set_visible(False)
 fig.suptitle('Does unrelated work still make progress?',fontsize=17,x=.035,ha='left',y=.97);fig.text(.035,.03,'Real PostgreSQL · 240 requests/sec: 80% pressure work, 20% probes · three repeats per deployment and policy\nDashed line: all 48 probe requests/sec. Read p95, rejections, errors and pressure-work outcomes together in the table.',fontsize=10,color='#a9bfb0');fig.tight_layout(rect=(.01,.1,1,.9));fig.savefig(ROOT/'public/images/resource-isolation.png',dpi=150);plt.close(fig)
 fig,axes=plt.subplots(2,2,figsize=(16,11));specs=[('memory','mean_allocation_mib_per_service','Mean retained allocation per service · MiB','Sampled memory regulator'),('goroutines','mean_workers_per_service','Mean active child goroutines per service','Sampled goroutine regulator'),('writes','peak_write_kib_per_service','Maximum actual logical write bytes in flight · KiB','Atomic concurrent write-byte budget'),('hot-keys','peak_key_concurrency','Maximum concurrent work on any one key','Atomic per-key concurrency')]
 for ax,(phase,key,ylabel,title) in zip(axes.flat,specs):
  for si,strategy in enumerate(STRATEGIES):
   vals=[next(r for r in rows if r['profile']==profile and r['strategy']==strategy and r['phase']==phase)[key] for profile in PROFILES];ax.bar([i+(si-1)*.24 for i in range(4)],vals,width=.22,color=colors[strategy],label=strategy)
  ax.set_xticks(range(4),['Middleware\nfixed','Proxy\nfixed','Middleware\nadaptive','Proxy\nadaptive']);ax.set_ylabel(ylabel);ax.set_title(title,pad=15);ax.set_ylim(bottom=0);ax.grid(axis='y',alpha=.12);ax.set_axisbelow(True);ax.spines[['top','right']].set_visible(False)
  if phase=='writes':ax.axhline(256,color='#bbd6c6',linestyle='--',linewidth=1)
  if phase=='hot-keys':ax.axhline(1,color='#bbd6c6',linestyle='--',linewidth=1)
 axes[0,0].legend(loc='upper right',frameon=False,labelcolor='#dae8df');fig.suptitle('What happens to the resources themselves?',fontsize=17,x=.035,ha='left',y=.97);fig.text(.035,.025,'Runtime charts use staggered ~100 ms samples, averaged over all three services/runs; bursts and peaks can be missed.\nWrite/key charts retain the largest instrumented peak from any service/repeat. Runtime sampling is reactive; it is not a hard allocation or goroutine cap.',fontsize=10,color='#a9bfb0');fig.tight_layout(rect=(.01,.08,1,.93));fig.savefig(ROOT/'public/images/resource-pressure.png',dpi=150);plt.close(fig)
 (out/'resource-chart-provenance.json').write_text(json.dumps({'source_sha256':summary['source_sha256'],'overhead_sha256':hashlib.sha256(overhead.encode()).hexdigest(),'aggregation':'Median run-level probe/success rates and successful p95; pooled rejection/error percentages. Runtime means pool staggered samples over three services/repeats. Byte/key peaks use maximum instrumented peak across services/repeats. SQL wait averages divide total duration by acquisitions that waited.','limitations':'Local short workload, explicit GC/page cleanup between phases. Sampled memory/goroutine feedback can overshoot or oscillate. Goroutine workers wait; no CPU scheduler-health claim. Source failures/unknown fallback are retained in raw traces.','matplotlib':matplotlib.__version__,'images':['resource-isolation.png','resource-pressure.png']},indent=2)+'\n');print('Exported',summary['sent'],'requests;',summary['checks'],'checks')
if __name__=='__main__':main()
